/* sandbox: the primitives a behaviour may use */
typedef struct {
    void *ctx;                                     /* engine state, opaque to behaviours */
    void (*play_sound)(void *ctx, int id, float volume);
    void (*spawn_particles)(void *ctx, int kind, int count);
    void (*move)(void *ctx, float x, float y, float z);
} sandbox;

static void sky_launch(sandbox *sb) {              /* the "sandbox method" */
    sb->play_sound(sb->ctx, SOUND_SPROING, 1.0f);
    sb->spawn_particles(sb->ctx, PARTICLE_DUST, 10);
    sb->move(sb->ctx, 0, 0, 20);
}
